to;height:3px;background:linear-gradient(90deg,var(--primary),transparent 72%);opacity:.8}.fitness-calculator__head{display:flex;align-items:flex-start;gap:12px}.fitness-calculator__icon{width:44px;height:44px;flex:none;display:grid;place-items:center;border-radius:14px;background:color-mix(in srgb,var(--primary) 14%,transparent);border:1px solid color-mix(in srgb,var(--primary) 28%,transparent);color:var(--primary-text);font-size:20px}.fitness-calculator h3{margin:1px 0 4px;color:var(--text-1);font:700 17px var(--font-tech)}.fitness-calculator__head p{margin:0;color:var(--text-3);font-size:12px;line-height:1.45}.calc-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.calc-fields .span-2{grid-column:span 2}.calc-field{display:grid;gap:6px}.calc-field label{color:var(--text-3);font:700 10.5px var(--font-tech);letter-spacing:.1em;text-transform:uppercase}.calc-field input,.calc-field select{min-width:0;width:100%;box-sizing:border-box;padding:11px 12px;border:1px solid var(--border);border-radius:11px;outline:none;background:var(--bg2);color:var(--text-1);font:600 14px var(--font-body);transition:border-color .2s,box-shadow .2s}.calc-field input:focus,.calc-field select:focus{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 15%,transparent)}.calc-run{width:100%;justify-content:center}.calc-result{display:none;padding:14px 15px;border:1px solid color-mix(in srgb,var(--primary) 25%,var(--border));border-radius:13px;background:color-mix(in srgb,var(--primary) 9%,var(--bg2));color:var(--text-2);font-size:13px;line-height:1.55}.calc-result b{display:block;margin-bottom:3px;color:var(--text-1);font:700 21px var(--font-disp)}.calc-result strong{color:var(--primary-text)}.calc-note{max-width:1280px;margin:20px auto 0;padding:14px 16px;border:1px solid var(--border);border-radius:14px;background:var(--surface);color:var(--text-3);font-size:12px;line-height:1.6}.calc-note b{color:var(--warning-text)}@media(max-width:760px){.calc-hero{min-height:280px;padding:62px 18px 110px}.calc-suite{margin-top:-58px;padding:0 16px 58px}.calc-suite__intro{display:block}.calc-suite__intro p{margin-top:7px}.calc-grid{grid-template-columns:1fr}.fitness-calculator{padding:20px}}@media(max-width:400px){.calc-fields{grid-template-columns:1fr}.calc-fields .span-2{grid-column:auto}}
