<script>
const ccaNum=id=>Number(document.getElementById(id).value);const ccaShow=(id,html)=>{const el=document.getElementById(id);el.innerHTML=html;el.style.display='block'};const ccaValid=(...values)=>values.every(v=>Number.isFinite(v)&&v>0);const ccaRound=n=>Math.round(n).toLocaleString();
function ccaBmi(){const h=ccaNum('bmiH')/100,w=ccaNum('bmiW');if(!ccaValid(h,w))return;const bmi=w/(h*h),cat=bmi<18.5?'Below the standard range':bmi<25?'Within the standard range':bmi<30?'Above the standard range':'High range — consider professional support';ccaShow('bmiResult',`<b>${bmi.toFixed(1)} BMI</b><strong>${cat}</strong> · A healthy BMI range at this height is ${(18.5*h*h).toFixed(1)}–${(24.9*h*h).toFixed(1)} kg.`)}
function ccaTdee(){const a=ccaNum('tAge'),h=ccaNum('tH'),w=ccaNum('tW'),act=ccaNum('tAct'),goal=ccaNum('tGoal');if(!ccaValid(a,h,w,act))return;const bmr=(document.getElementById('tSex').value==='m'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161),tdee=bmr*act,target=Math.max(1200,tdee+goal);ccaShow('tdeeResult',`<b>${ccaRound(target)} kcal / day</b><strong>Maintenance: ${ccaRound(tdee)} kcal</strong> · BMR: ${ccaRound(bmr)} kcal. Review after 2–3 weeks of real progress.`)}
function ccaMacro(){const c=ccaNum('mCals');if(!ccaValid(c))return;const goal=document.getElementById('mGoal').value,p=goal==='cut'?.35:goal==='gain'?.28:.30,carb=goal==='cut'?.35:goal==='gain'?.50:.45,fat=1-p-carb;ccaShow('macroResult',`<b>${ccaRound(c*p/4)}g protein · ${ccaRound(c*carb/4)}g carbs · ${ccaRound(c*fat/9)}g fats</b><strong>${goal==='cut'?'Higher protein for fat loss':goal==='gain'?'More carbohydrate for training fuel':'Balanced maintenance split'}</strong> · Adjust based on preference, performance and recovery.`)}
function ccaWater(){const w=ccaNum('waterW'),mins=ccaNum('waterMin');if(!Number.isFinite(w)||w<=0||!Number.isFinite(mins)||mins<0)return;const litres=w*.033+(mins/30)*.35;ccaShow('waterResult',`<b>${litres.toFixed(1)} L / day</b><strong>About ${ccaRound(litres*4)} cups</strong> · Includes a ${ccaRound((mins/30)*.35*1000)} ml training adjustment. Heat and sweat rate can raise needs.`)}
function ccaIdeal(){const cm=ccaNum('idealH');if(!ccaValid(cm))return;const inches=cm/2.54,base=document.getElementById('idealSex').value==='m'?50:45.5,devine=base+2.3*Math.max(0,inches-60),h=cm/100;ccaShow('idealResult',`<b>${devine.toFixed(1)} kg Devine estimate</b><strong>Healthy BMI range: ${(18.5*h*h).toFixed(1)}–${(24.9*h*h).toFixed(1)} kg</strong> · Frame size, muscle mass and health context matter more than one number.`)}
function ccaBodyFat(){const sex=document.getElementById('bfSex').value,h=ccaNum('bfH'),waist=ccaNum('bfWaist'),neck=ccaNum('bfNeck'),hip=ccaNum('bfHip');if(!ccaValid(h,waist,neck)||(sex==='f'&&!ccaValid(hip)))return;const log=Math.log10;const density=sex==='m'?1.0324-.19077*log(waist-neck)+.15456*log(h):1.29579-.35004*log(waist+hip-neck)+.221*log(h);const fat=495/density-450;if(!Number.isFinite(fat)||fat<2||fat>65)return ccaShow('bodyFatResult','<b>Check the measurements</b><strong>Use centimetres and make sure waist / hip values are larger than neck.</strong>');ccaShow('bodyFatResult',`<b>${fat.toFixed(1)}% estimated body fat</b><strong>US Navy circumference estimate</strong> · Measure consistently at the same time of day; it is not a clinical body-composition test.`)}
function ccaOneRm(){const load=ccaNum('rmWeight'),reps=ccaNum('rmReps');if(!ccaValid(load,reps)||reps>20)return;const one=load*(1+reps/30);ccaShow('oneRmResult',`<b>${one.toFixed(1)} kg estimated 1RM</b><strong>75% training load: ${(one*.75).toFixed(1)} kg</strong> · Best used for submaximal sets of 1–10 reps with clean technique.`)}
function ccaHeartRate(){const age=ccaNum('hrAge'),rest=ccaNum('hrRest');if(!ccaValid(age,rest))return;const max=208-.7*age,reserve=max-rest,z=(a,b)=>`${ccaRound(rest+reserve*a)}–${ccaRound(rest+reserve*b)}`;ccaShow('heartResult',`<b>Estimated max: ${ccaRound(max)} bpm</b><strong>Easy ${z(.5,.6)} · Aerobic ${z(.6,.7)} · Tempo ${z(.7,.8)} · Hard ${z(.8,.9)} bpm</strong> · Stop if you feel chest pain, dizziness or unusual breathlessness.`)}
</script>
